window.addEventListener('scroll', throttle(function() {
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop;
    if (scrollTop < 10) {
        document.body.classList.remove('body-scroll');
    } else {
        document.body.classList.add('body-scroll');
    }
}, 100)); // 每100毫秒最多执行一次

$(function() {
    // 初始化时检查Cookie并设置主题
    const theme = getCookie('theme');
    if (theme === 'dark') {
        document.body.classList.add('dark-theme');
    }
    //console.log(theme);
    $(".toggle-theme").click(function () {
        const isDark = document.body.classList.toggle('dark-theme');
        // 根据当前主题状态设置或删除Cookie
        if (isDark) {
            setCookie('theme', 'dark');
        } else {
            deleteCookie('theme');
            //console.log(3333);
        }
    });
    $(".mobile-navbar-toggle").click(function () {
        document.body.classList.toggle('mobile-navbar-show');
    });
    $(".serach-switch").click(function () {
        $("#nav_search").toggleClass('show');
    });
    $(".itmkk-top").click(function () {
        window.scrollTo({
            top: 0,
            behavior: "smooth"
        });
    });
    var img=$("#post-body-888888 img");
    for(var i=0;i<img.length;i++){
        // 设置图片属性
        img.eq(i).attr("data-fancybox",'gallery')
    }
});
$(document).ready(function() {
    // 点击 mobile-respond 切换显示
    $(document).on('click', '#mobile-respond', function(e) {
        e.stopPropagation();
        $(".mobile-fixed").toggleClass('show');
    });

    // 点击文档其他部分关闭（使用事件委托）
    $(document).on('click', function(e) {
        // 关闭 mobile-fixed
        if (!$(e.target).closest('.mobile-fixed').length &&
            !$(e.target).is('#mobile-respond')) {
            $(".mobile-fixed").removeClass('show');
        }

        // 关闭 dropup
        if (!$(e.target).closest('.dropup').length) {
            $('.dropup.open').removeClass('open');
        }
    });

    // 阻止 mobile-fixed 内容点击时冒泡
    $(document).on('click', '.mobile-fixed', function(e) {
        e.stopPropagation();
    });

    //--------------- 回复评论相关操作 ---------------------------
    // 存储原始表单HTML和位置
    const originalFormHtml = $('#respond').prop('outerHTML');
    const originalFormPosition = $('#respond').parent();
    let isFormMoved = false;

    // 为所有回复链接添加点击事件
    $(document).on('click', '.comment-reply-link', function(e) {
        e.preventDefault();
        e.stopPropagation();

        const repId = $(this).data('commentid');
        const currentComment = $(this).closest('.comt-main');

        // 创建占位div（只在第一次移动时）
        if (!isFormMoved) {
            originalFormPosition.append('<div id="wp-temp-form-div" style="display: none;"></div>');
        }

        // 如果表单已经在页面上，先移除
        if ($('#respond').length) {
            $('#respond').detach();
        }

        // 移动表单到当前评论下方
        currentComment.after(originalFormHtml);
        isFormMoved = true;

        // 显示表单
        $('#respond').addClass('show');

        // 存储当前回复的评论ID
        $('#comment_parent').val(repId);

        // 重新绑定表情按钮事件（因为DOM被替换）
        bindEmoticonEvents();

        // 滚动到表单位置
        // $('html, body').animate({
        //     scrollTop: $('#respond').offset().top - 100
        // }, 300);
    });

    // 取消回复功能 - 返回原始位置
    $(document).on('click', '#cancel-comment-reply-link', function(e) {
        e.stopPropagation();
        $('#respond').remove();
        originalFormPosition.prepend(originalFormHtml);
        isFormMoved = false;

        // 重新绑定表情按钮事件
        bindEmoticonEvents();
    });

    //--------------- 表情按钮相关操作 ---------------------------
    // 初始化绑定表情按钮事件
    bindEmoticonEvents();

    // 绑定表情按钮事件的函数
    function bindEmoticonEvents() {
        // 解绑旧事件避免重复绑定
        $(document).off('click', '.dropup');
        // 点击文档其他部分关闭
        $('.fixed-body').on('click', function(e) {
            // $(".mobile-fixed").removeClass('show');
            e.stopPropagation();
            $('#respond').remove();
            originalFormPosition.prepend(originalFormHtml);
            isFormMoved = false;

            // 重新绑定表情按钮事件
            bindEmoticonEvents();
        });
        // 使用事件委托绑定新事件
        $(document).on('click', '.dropup', function(e) {
            e.stopPropagation();
            var $current = $(this);

            if ($current.hasClass('open')) {
                $current.removeClass('open');
            } else {
                $('.dropup.open').removeClass('open');
                $current.addClass('open');
            }
        });
    }
});

function throttle(func, limit) {
    let lastFunc;
    let lastRan;
    return function() {
        const context = this;
        const args = arguments;
        if (!lastRan) {
            func.apply(context, args);
            lastRan = Date.now();
        } else {
            clearTimeout(lastFunc);
            lastFunc = setTimeout(function() {
                if ((Date.now() - lastRan) >= limit) {
                    func.apply(context, args);
                    lastRan = Date.now();
                }
            }, limit - (Date.now() - lastRan));
        }
    }
}
/**
 * 设置Cookie
 * @param {string} name Cookie名称
 * @param {string} value Cookie值
 * @param {number} [days] 过期天数（可选）
 */
function setCookie(name, value, days) {
    let cookie = `${encodeURIComponent(name)}=${encodeURIComponent(value)}`;
    // 设置过期时间
    if (days) {
        const date = new Date();
        date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
        cookie += `; expires=${date.toUTCString()}`;
    }

    // 设置路径和域
    cookie += `; path=/`;
    cookie += `; domain=${getCurrentDomain()}`;

    document.cookie = cookie;
}

/**
 * 获取Cookie值
 * @param {string} name Cookie名称
 * @returns {string|null} Cookie值
 */
function getCookie(name) {
    const value = `; ${document.cookie}`;
    const parts = value.split(`; ${encodeURIComponent(name)}=`);
    if (parts.length === 2) return decodeURIComponent(parts.pop().split(';').shift());
    return null;
}

/**
 * 删除Cookie
 * @param {string} name Cookie名称
 */
function deleteCookie(name) {
    document.cookie = `${encodeURIComponent(name)}=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/; domain=${getCurrentDomain()}`;
}

/**
 * 获取当前域名（处理子域名情况）
 * @returns {string} 当前域名
 */
function getCurrentDomain() {
    const hostname = window.location.hostname;
    // 如果是localhost或IP地址，直接返回
    if (hostname === 'localhost' || /^\d+\.\d+\.\d+\.\d+$/.test(hostname)) {
        return hostname;
    }
    // 处理主域名（如从www.example.com获取example.com）
    const parts = hostname.split('.');
    return parts.length > 2 ? parts.slice(-2).join('.') : hostname;
}
function scrollToComments() {
    const target = document.querySelector('#comments');
    if (target) {
        window.scrollTo({
            top: target.getBoundingClientRect().top + window.pageYOffset - 50,
            behavior: 'smooth'
        });
        return true;
    }
    return false;
}
function ClickLike(id){
    var like = getCookie('like-'+id);
    if(like){
        layer.closeAll();
        layer.msg('已赞过此文章了',{icon:0});
        return false;
    }
    layer.load();
    //console.log(like);
    $.ajax({
        url: '/index/detail/action',
        type: "POST",
        data: {id:id},
        success: function (data) {
            let obj = JSON.parse(data);
            if(obj.code == 200){
                //关闭弹出层
                layer.closeAll();
                $('#ViewsClick').html(obj.data.click)
                layer.msg(obj.msg,{icon:1,time:3000,shade:0.3});
                setCookie('like-'+obj.id,obj.id,365);
            }else{
                layer.closeAll(); //关闭加载层
                layer.msg(obj.msg,{icon:2,time:3000,shade:0.3});
            }
        },
        error: function () {
            layer.msg("上传失败！",{icon:2,time:2000,shade:0.3});
            $("#imgWait").hide();
            layer.closeAll('loading'); //关闭加载层
        }
    });
}

